    /// Only deliberate input postpones the lock: not window bookkeeping like
    /// a focus change, and not the pointer merely moving over the window.
    #[test]
    fn user_activity_is_deliberate_input_only() {
        assert!(is_user_activity(&egui::Event::Text("a".into())));
        assert!(is_user_activity(&egui::Event::PointerButton {
            pos: egui::pos2(1.0, 2.0),
            button: egui::PointerButton::Primary,
            pressed: true,
            modifiers: egui::Modifiers::NONE,
        }));
        assert!(!is_user_activity(&egui::Event::PointerMoved(egui::pos2(
            1.0, 2.0
        ))));
        assert!(!is_user_activity(&egui::Event::MouseMoved(egui::vec2(
            1.0, 0.0
        ))));
        assert!(!is_user_activity(&egui::Event::WindowFocused(true)));
        assert!(!is_user_activity(&egui::Event::PointerGone));
    }

    /// A listing clears the idle-lock notice, and keeps an HOTP code read on
    /// demand (it doesn't expire; the listing never computes one).
    #[test]
    fn oath_listing_clears_the_notice_and_keeps_hotp_codes() {
        let mut app = App::default();
        app.oath.notice = Some(idle_hidden_msg());
        app.oath.creds = vec![OathRow::new(
            "Example:bob".into(),
            Some("111111".into()),
            true,
        )];
        let rows = vec![
            OathRow::new("Example:bob".into(), None, true),
            OathRow::new("Example:alice".into(), Some("222222".into()), false),
        ];
        App::apply_oath_rows(
            &mut app,
            Ok((rows, 0)),
            zeroize::Zeroizing::new(String::new()),
        );
        assert_eq!(app.oath.notice, None);
        assert_eq!(app.oath.creds[0].code.as_deref(), Some("111111"));
        assert_eq!(app.oath.creds[1].code.as_deref(), Some("222222"));
    }

    /// TOTP rows that needed a touch stay marked across a listing, and only
    /// they are handed to the next listing to leave alone, so the per-window
    /// re-read never waits for a touch.
    #[test]
    fn oath_touch_rows_are_left_to_on_request_reads() {
        let mut app = App::default();
        let mut touch = OathRow::new("Example:touchy".into(), None, false);
        touch.touch = true;
        let rows = vec![
            OathRow::new("Example:alice".into(), Some("222222".into()), false),
            touch,
            OathRow::new("Example:bob".into(), None, true),
        ];
        App::apply_oath_rows(
            &mut app,
            Ok((rows, 0)),
            zeroize::Zeroizing::new(String::new()),
        );
        assert!(app.oath.creds[1].touch);
        assert_eq!(app.oath_touch_names(), vec!["Example:touchy".to_string()]);
    }

    fn oath_cred(name: &str, hotp: bool) -> keyroost_oath::CredentialInfo {
        keyroost_oath::CredentialInfo {
            name: name.into(),
            oath_type: if hotp {
                keyroost_oath::OathType::Hotp
            } else {
                keyroost_oath::OathType::Totp
            },
            algorithm: keyroost_oath::Algorithm::Sha1,
        }
    }

    fn calc_all(
        entries: &[(&str, keyroost_oath::CalculateAllResult)],
    ) -> keyroost_oath::CalculateAll {
        keyroost_oath::CalculateAll {
            entries: entries
                .iter()
                .map(|(n, r)| keyroost_oath::CalculateAllEntry {
                    name: (*n).into(),
                    result: r.clone(),
                })
                .collect(),
            skipped: 0,
        }
    }

    fn code(c: &str) -> keyroost_oath::CalculateAllResult {
        keyroost_oath::CalculateAllResult::Code(keyroost_oath::OtpCode {
            digits: 6,
            code: c.into(),
        })
    }

    /// With CALCULATE ALL the card answers every 30-second code at once and
    /// flags touch accounts itself, so nothing waits for a touch. Only a
    /// non-30-second account (its code came back for the wrong window) and an
    /// account missing from the answer are read one by one.
    #[test]
    fn oath_rows_use_calculate_all() {
        use keyroost_oath::CalculateAllResult::{Hotp, Touch};
        let creds = vec![
            oath_cred("A:totp", false),
            oath_cred("B:touch", false),
            oath_cred("60/C:minute", false),
            oath_cred("D:hotp", true),
            oath_cred("E:missing", false),
        ];
        let all = calc_all(&[
            ("A:totp", code("111111")),
            ("B:touch", Touch),
            ("60/C:minute", code("999999")),
            ("D:hotp", Hotp),
        ]);
        let mut reads = Vec::new();
        let rows = App::oath_rows_from(creds, Some(&all), &[], |name, period| {
            reads.push((name.to_owned(), period));
            Some(format!("{period:06}"))
        });
        assert_eq!(
            reads,
            vec![("60/C:minute".to_owned(), 60), ("E:missing".to_owned(), 30)]
        );
        let by = |n: &str| rows.iter().find(|r| r.name == n).unwrap();
        assert_eq!(by("A:totp").code.as_deref(), Some("111111"));
        assert!(by("B:touch").touch && by("B:touch").code.is_none());
        assert_eq!(by("60/C:minute").code.as_deref(), Some("000060"));
        assert!(by("D:hotp").hotp && by("D:hotp").code.is_none());
        assert_eq!(by("E:missing").code.as_deref(), Some("000030"));
        assert!(rows.last().unwrap().hotp, "HOTP rows sort last");
    }

    /// A key that refuses CALCULATE ALL gets the one-by-one reads, skipping
    /// the accounts already known to need a touch.
    #[test]
    fn oath_rows_fall_back_without_calculate_all() {
        let creds = vec![
            oath_cred("A:totp", false),
            oath_cred("B:touch", false),
            oath_cred("C:slow", false),
        ];
        let mut reads = Vec::new();
        let rows = App::oath_rows_from(creds, None, &["B:touch".to_owned()], |name, _| {
            reads.push(name.to_owned());
            (name == "A:totp").then(|| "222222".to_owned())
        });
        assert_eq!(reads, vec!["A:totp".to_owned(), "C:slow".to_owned()]);
        assert_eq!(rows[0].code.as_deref(), Some("222222"));
        assert!(rows[1].touch, "known touch account is not read");
        assert!(
            rows[2].touch,
            "a read that gives nothing back is a touch account"
        );
    }

    /// Refresh is the only reload button, so it re-reads whatever section is
    /// open: the FIDO2 sub-tab's own list, not just the key's info.
    #[test]
    fn refresh_rereads_the_open_section() {
        let mut app = App {
            cap_tab: CapTab::Fido2,
            ..Default::default()
        };
        app.security_keys.subview = FidoSubview::LargeBlobs;
        assert_eq!(app.reread_choice(), Reread::LargeBlobs);
        // Passkeys and fingerprints need an unlocked key; locked, Refresh
        // reads the key's info (PIN state) instead.
        app.security_keys.subview = FidoSubview::Passkeys;
        assert_eq!(app.reread_choice(), Reread::FidoInfo);
        app.security_keys.subview = FidoSubview::Fingerprints;
        assert_eq!(app.reread_choice(), Reread::FidoInfo);
        app.security_keys.subview = FidoSubview::Settings;
        assert_eq!(app.reread_choice(), Reread::FidoInfo);
        app.cap_tab = CapTab::Pgp;
        assert_eq!(app.reread_choice(), Reread::Pgp);
        // A password-locked Authenticator waits for its password.
        app.cap_tab = CapTab::Oath;
        app.oath.locked = true;
        assert_eq!(app.reread_choice(), Reread::Nothing);
        app.oath.locked = false;
        assert_eq!(app.reread_choice(), Reread::Oath);
    }

